package com.example.redirects;

/** Where to send a user after sign-in. */
public final class Redirects {
    private Redirects() {
    }

    public static String afterLogin(String target) {
        if (target == null || target.isEmpty()) {
            return "/";
        }
        return target;
    }
}

package com.example.redirects;

import static org.junit.jupiter.api.Assertions.assertEquals;

import org.junit.jupiter.api.Test;

class RedirectsTest {
    @Test
    void defaultsToHome() {
        assertEquals("/", Redirects.afterLogin(null));
    }
}
